-- PT105-S4-Q7. Batch 10.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT105-S4-Q7$batch10$ AND q.stimulus=$batch10$Willett: Lopez and Simmons, a married couple, have both been offered jobs at Evritech Corporation. Because Evritech has a rule against hiring more than one member of the same family, Lopez and Simmons have decided to reveal their marriage to Evritech. Their decision is foolish, however, since it will mean that one of them will have a job offer withdrawn. After all, they could easily keep their marriage secret initially and, if they want, later claim to have married after they were hired: Evritech has no policy of terminating one of two employees who marry each other.$batch10$ AND q.prompt=$batch10$Which one of the following principles, if valid, most helps to support the reasoning in Willett's argument?$batch10$ AND q.correct_choice=$batch10$E$batch10$) THEN RAISE EXCEPTION 'Question changed: PT105-S4-Q7'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch10$PT105-S4-Q7$batch10$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT105-S4-Q7'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT105-S4-Q7$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Conclusion$batch10$, $batch10$Lopez and Simmons are foolish to reveal their marriage to Evritech.$batch10$), (1, $batch10$Evidence$batch10$, $batch10$Revealing it means one of them loses the job offer. They could keep the marriage secret and later say they married after being hired, and Evritech has no policy of firing one of two employees who marry.$batch10$), (2, $batch10$Evaluate$batch10$, $batch10$Willett's advice only works if the couple is allowed to stay quiet about their marriage. If they had a duty to tell Evritech, keeping it secret wouldn't be a sensible option. The principle has to remove that duty.$batch10$), (3, $batch10$Goal$batch10$, $batch10$Job candidates have no obligation to tell an employer about their marriage.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT105-S4-Q7$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$This is about what Evritech's policy should be. Willett is advising the couple about what to do under the policy that exists.$batch10$), ($batch10$B$batch10$, $batch10$This says when a company should adopt the one-family rule. It doesn't help show that the couple is foolish to disclose.$batch10$), ($batch10$C$batch10$, $batch10$If withholding requested information is as bad as lying, the couple shouldn't keep quiet. That undercuts Willett's advice.$batch10$), ($batch10$D$batch10$, $batch10$This says candidates who can't follow a company's policies should turn down the job. It points toward the couple declining, not toward keeping the marriage secret.$batch10$), ($batch10$E$batch10$, $batch10$If candidates don't have to reveal marital status whatever the employer's policies, then the couple can keep quiet without doing anything wrong. That makes revealing the marriage, and losing an offer, the foolish choice.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT105-S4-Q7$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
